begin;
create schema rep_test;
create table rep_test.results(name text primary key,passed boolean);
create table rep_test.state(k text primary key,v jsonb);
grant usage on schema rep_test to anon,authenticated; grant all on all tables in schema rep_test to anon,authenticated;
create function rep_test.assert(name text,ok boolean) returns void language plpgsql as $$ begin if ok is distinct from true then raise exception 'ASSERTION FAILED: %',name; end if; insert into rep_test.results values(name,true); end $$;
create function rep_test.denied(name text,command text,expected text) returns void language plpgsql as $$ declare caught boolean:=false; begin begin execute command; exception when others then if sqlerrm not like '%'||expected||'%' then raise; end if; caught:=true; end; perform rep_test.assert(name,caught); end $$;
insert into auth.users(id,email_confirmed_at) values('70000000-0000-4000-8000-000000000001',now()),('70000000-0000-4000-8000-000000000002',now());
insert into public.movies(id,tmdb_id,title,original_title) values('70000000-0000-4000-8000-000000000003',77777,'Representation fixture','Representation fixture');
set local role anon;
select rep_test.assert('empty representation not absence',public.get_representation('70000000-0000-4000-8000-000000000003','{}',0::smallint)='{"representation":[]}'::jsonb);
select rep_test.assert('empty family unknown',public.get_family_summary('70000000-0000-4000-8000-000000000003')->'familySummary' @> '{"value":null,"count":0,"distribution":[0,0,0,0,0],"provisional":false}');
select rep_test.denied('anonymous cannot write representation',$cmd$select public.put_representation(null,0,true,'lgbtq_characters',0::smallint,false,'rep-denied')$cmd$,'permission denied');
set local role authenticated;
select set_config('request.jwt.claim.sub','70000000-0000-4000-8000-000000000001',true);
insert into rep_test.state values('first',public.put_representation('70000000-0000-4000-8000-000000000003',0,true,'lgbtq_characters',0::smallint,false,'rep-first'));
select rep_test.assert('own representation positive without severity',(select v from rep_test.state where k='first')->'representation'->'details'='[{"slug":"lgbtq_characters","spoilerLevel":0}]'::jsonb);
select rep_test.assert('representation creates no warning ratings',public.get_my_contribution('70000000-0000-4000-8000-000000000003')->'contribution'->'ratings'='[]'::jsonb);
select rep_test.assert('repeat no extra vote',public.put_representation('70000000-0000-4000-8000-000000000003',0,true,'lgbtq_characters',0::smallint,false,'rep-first')=(select v from rep_test.state where k='first'));
select rep_test.denied('negative spoiler rejected',$cmd$select public.put_representation('70000000-0000-4000-8000-000000000003',0,true,'lgbtq_characters',-1::smallint,false,'rep-negative')$cmd$,'INVALID_REQUEST');
select rep_test.denied('none tag unsupported',$cmd$select public.put_representation('70000000-0000-4000-8000-000000000003',0,true,'none',0::smallint,false,'rep-none')$cmd$,'INVALID_REQUEST');
select rep_test.denied('watch confirmation required',$cmd$select public.put_representation('70000000-0000-4000-8000-000000000003',0,false,'lgbtq_characters',0::smallint,false,'rep-unwatched')$cmd$,'WATCH_CONFIRMATION_REQUIRED');
select rep_test.denied('stale own revision rejects',$cmd$select public.put_representation('70000000-0000-4000-8000-000000000003',0,true,'lgbtq_themes',0::smallint,false,'rep-stale')$cmd$,'REVISION_CONFLICT');
insert into rep_test.state values('hidden',public.put_representation('70000000-0000-4000-8000-000000000003',((select v from rep_test.state where k='first')->'representation'->>'revision')::bigint,true,'same_sex_romance',2::smallint,false,'rep-hidden'));
set local role anon;
select rep_test.assert('level2 suppresses related visible tags',public.get_representation('70000000-0000-4000-8000-000000000003','{}',0::smallint)='{"representation":[]}'::jsonb);
select rep_test.assert('default summary no hidden counts',(public.get_movie_summary('70000000-0000-4000-8000-000000000003')->'representation')='[]'::jsonb);
select rep_test.assert('level1 remains hidden',public.get_representation('70000000-0000-4000-8000-000000000003',array['lgbtq_characters'],1::smallint)='{"representation":[]}'::jsonb);
select rep_test.assert('selected reveal contains only selected tag',public.get_representation('70000000-0000-4000-8000-000000000003',array['same_sex_romance'],2::smallint)='{"representation":[{"slug":"same_sex_romance","count":1,"provisional":true}]}'::jsonb);
select rep_test.denied('reveal all forbidden',$cmd$select public.get_representation('70000000-0000-4000-8000-000000000003','{}',2::smallint)$cmd$,'INVALID_REQUEST');
select rep_test.assert('no family derived from representation',public.get_family_summary('70000000-0000-4000-8000-000000000003')->'familySummary'->>'count'='0');
set local role authenticated;
select set_config('request.jwt.claim.sub','70000000-0000-4000-8000-000000000002',true);
select rep_test.assert('other account sees no own details',public.get_my_representation('70000000-0000-4000-8000-000000000003')='{"representation":null}'::jsonb);
select rep_test.denied('other account cannot use author revision',$cmd$select public.put_representation('70000000-0000-4000-8000-000000000003',((select v from rep_test.state where k='hidden')->'representation'->>'revision')::bigint,true,'same_sex_romance',0::smallint,true,'rep-other')$cmd$,'REVISION_CONFLICT');
select public.put_family_vote('70000000-0000-4000-8000-000000000003',0,true,5::smallint,'rep-familytwo');
select set_config('request.jwt.claim.sub','70000000-0000-4000-8000-000000000001',true);
select public.put_family_vote('70000000-0000-4000-8000-000000000003',0,true,1::smallint,'rep-familyone');
set local role anon;
select rep_test.assert('family upper median independent',public.get_family_summary('70000000-0000-4000-8000-000000000003')->'familySummary' @> '{"value":5,"count":2,"distribution":[1,0,0,0,1],"provisional":true}');
select rep_test.assert('family absent default summary',not public.get_movie_summary('70000000-0000-4000-8000-000000000003') ? 'familySummary');
reset role;
update private.user_access set status='suspended' where user_id='70000000-0000-4000-8000-000000000001';
set local role anon;
select rep_test.assert('suspended representation excluded',public.get_representation('70000000-0000-4000-8000-000000000003',array['same_sex_romance'],2::smallint)='{"representation":[]}'::jsonb);
select rep_test.assert('suspended family excluded',public.get_family_summary('70000000-0000-4000-8000-000000000003')->'familySummary'->>'count'='1');
reset role;
update private.user_access set status='active' where user_id='70000000-0000-4000-8000-000000000001';
set local role authenticated;
select set_config('request.jwt.claim.sub','70000000-0000-4000-8000-000000000001',true);
reset role;
insert into public.category_ratings(contribution_id,category_slug,severity) select id,'language',1 from public.contributions where movie_id='70000000-0000-4000-8000-000000000003' and user_id='70000000-0000-4000-8000-000000000001';
set local role authenticated;
insert into rep_test.state values('removed',public.put_representation('70000000-0000-4000-8000-000000000003',((select v from rep_test.state where k='hidden')->'representation'->>'revision')::bigint,true,'same_sex_romance',0::smallint,true,'rep-remove'));
select rep_test.assert('individual representation removal preserves warning ratings',public.get_my_contribution('70000000-0000-4000-8000-000000000003')->'contribution'->'ratings' @> '[{"category":"language","severity":1}]'::jsonb);
select rep_test.assert('individual withdrawal keeps other tag',(select v from rep_test.state where k='removed')->'representation'->'details'='[{"slug":"lgbtq_characters","spoilerLevel":0}]'::jsonb);
select public.delete_contribution('70000000-0000-4000-8000-000000000003',((select v from rep_test.state where k='removed')->'representation'->>'revision')::bigint,'rep-delete');
set local role anon;
select rep_test.assert('full contribution withdrawal removes representation',public.get_representation('70000000-0000-4000-8000-000000000003','{}',0::smallint)='{"representation":[]}'::jsonb);
select * from rep_test.results;
rollback;
